package com.exe201.rrms.controller;
import com.exe201.rrms.service.*; import com.exe201.rrms.entity.*; import com.exe201.rrms.repository.*; import jakarta.servlet.http.HttpServletRequest; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/marketplace") public class MarketplaceController { private final MarketplaceService market; private final ListingRepository listings; private final PropertyRepository props; private final AuthService auth; public MarketplaceController(MarketplaceService m,ListingRepository l,PropertyRepository p,AuthService a){market=m;listings=l;props=p;auth=a;} @GetMapping("/listings") public List<Map<String,Object>> search(@RequestParam Map<String,String> q){return market.search(q);} @GetMapping("/listings/{id}") public Map<String,Object> detail(@PathVariable Long id){Listing l=listings.findById(id).orElseThrow();l.setViewCount((l.getViewCount()==null?0:l.getViewCount())+1);listings.save(l);return market.detailByListing(id);} @GetMapping("/listings/{id}/contact") public Map<String,Object> contact(@PathVariable Long id,HttpServletRequest req){auth.current(req);Listing l=listings.findById(id).orElseThrow();Property p=props.findById(l.getPropertyId()).orElseThrow();return Map.of("phone",Objects.toString(p.getContactPhone(),""),"zalo",Objects.toString(p.getContactZalo(),""));} }
